1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	
4	const BASE_PREMIUM: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: 25,
10	  moonstone: 25,
11	};
12	
13	interface Item {
14	  type: string;
15	}
16	
17	interface QuoteStep {
18	  op: "quote";
19	  items: Item[];
20	}
21	
22	interface Scenario {
23	  customer: { yearsWithMHPCO: number };
24	  steps: QuoteStep[];
25	}
26	
27	interface QuoteResult {
28	  premium: number;
29	}
30	
31	interface ScenarioResult {
32	  results: QuoteResult[];
33	}
34	
35	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
36	const COMPONENT_BLOCK_SIZE = 3;
37	const COMPONENT_BLOCK_BASE = 60;
38	
39	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
40	
41	const groupCountsByType = (items: Item[]): Map<string, number> => {
42	  const counts = new Map<string, number>();
43	  for (const item of items) {
44	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
45	  }
46	  return counts;
47	};
48	
49	const typeBasePremium = (type: string, count: number): number => {
50	  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
51	    return COMPONENT_BLOCK_BASE;
52	  }
53	  return BASE_PREMIUM[type] * count;
54	};
55	
56	const itemsBasePremium = (items: Item[]): number => {
57	  let total = 0;
58	  for (const [type, count] of groupCountsByType(items)) {
59	    total += typeBasePremium(type, count);
60	  }
61	  return total;
62	};
63	
64	const quotePremium = (step: QuoteStep): number => {
65	  const base = itemsBasePremium(step.items);
66	  const firstInsuranceSurcharge = base * FIRST_INSURANCE_RATE;
67	  return roundUpInMHPCOsFavor(base + firstInsuranceSurcharge + PROCESSING_FEE);
68	};
69	
70	export const runScenario = (scenario: Scenario): ScenarioResult => ({
71	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
72	});
