84	    const result = runScenario({
85	      customer: { yearsWithMHPCO: 0 },
86	      steps: [{ op: "quote", items: [
87	        { type: "rune" }, { type: "rune" }, { type: "moonstone" },
88	      ] }],
89	    });
90	    expect(result).toEqual({ results: [{ premium: 88 }] });
