116	  it.todo("policy with cursed sword and plain amulet → base 160 G; curse adds 50 G (of sword only) → 210 G before fee + first insurance");
117	
118	  // === Rounding in MHPCO's favor ===
119	  it.todo("premium calculation yielding 197.5 G → 198 G (rounded up)");
120	  it.todo("payout calculation yielding 350.5 G → 350 G (rounded down)");
121	
122	  // === Second contract / follow-up ===
123	  it.todo("customer's second quote → 15% follow-up discount applies to policy base");
124	
125	  // === First-insurance surcharge is per item ===
126	  it.todo("long-standing customer's second quote of a cursed sword (enchantment 7) → 160 G total (integration example)");
127	
128	  // === Newcomer integration example ===
129	  it.todo("newcomer cursed sword (steel, enchantment 3) integration example → 165 G");
130	
131	  // === Claims: basic ===
132	  it.todo("claim on regular sword (steel, enchantment 3), damage 500 G → payout 400 G (500 - 100 deductible)");
133	  it.todo("claim on rune (250 G insurance), damage 200 G → payout 100 G (200 - 100 deductible)");
134	
