136	  it.todo("claim on steel sword enchantment 9, damage 1000 G → payout 400 G (50% then -100 deductible)");
137	  it.todo("claim on dragon-material sword enchantment 8, damage 1000 G → payout 400 G (high-enchantment wins, then deductible)");
138	  it.todo("claim on dragon-material sword enchantment 5, damage 800 G → payout 700 G (dragon full, then deductible)");
139	  it.todo("claim on dragon-material sword enchantment 9, damage 1000 G → payout 400 G (50% wins, then deductible)");
140	
141	  // === Deductible per damage event ===
142	  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (100 deductible per item)");
143	
144	  // === Multiple items of same type ===
145	  it.todo("policy with two swords → insurance sum 2000 G, cap 4000 G");
146	  it.todo("dragon attack damages two swords → each entry treated separately with its own deductible");
147	  it.todo("claim with more sword damages than swords insured → CLI error, non-zero exit");
148	
149	  // === Cap and cap exhaustion ===
150	  it.todo("policy with sword and amulet → insurance sum 1600 G, cap 3200 G");
151	  it.todo("cursed sword premium modifiers don't affect cap → cap 2000 G");
152	  it.todo("policy with sword + 3 runes (block) → insurance sum 1750 G");
153	  it.todo("sword insured (cap 2000), first claim 1500 → payout 1400 G, cap remaining 600 G");
154	  it.todo("sword insured (cap 2000), second claim 1500 after first → payout 600 G, cap remaining 0 G");
